sys_script_include.script:
var CampusLoginSessionUtils = Class.create();

CampusLoginSessionUtils.prototype = Object.extendsObject(
    global.AbstractAjaxProcessor,
    {
        // ==========================================================
        // LOGIN
        // ==========================================================

        login: function() {

            gs.info(
                "CAMPUS LOGIN SCRIPT INCLUDE CALLED"
            );

            // ======================================================
            // 1. GET USERNAME AND PASSWORD FROM LOGIN FORM
            // ======================================================

            var username =
                this.getParameter("sysparm_username");

            var password =
                this.getParameter("sysparm_password");

            gs.info(
                "CAMPUS LOGIN USERNAME RECEIVED: " +
                username
            );


            // ======================================================
            // 2. CHECK USERNAME
            // ======================================================

            if (!username) {

                return JSON.stringify({

                    authentication: false,
                    userRole: "",
                    sessionId: "",
                    sessionNumber: "",
                    userName: "",
                    user: ""

                });
            }


            // ======================================================
            // 3. PASSWORD
            // ======================================================

            // Password is currently received but not validated.
            //
            // This can be changed later when real password
            // authentication is added.
            //
            // ======================================================


            // ======================================================
            // 4. FIND USER IN SYS_USER
            // ======================================================

            var userGR =
                new GlideRecord("sys_user");

            userGR.addQuery(
                "user_name",
                username
            );

            userGR.query();


            // ======================================================
            // 5. USER NOT FOUND
            // ======================================================

            if (!userGR.next()) {

                return JSON.stringify({

                    authentication: false,
                    userRole: "",
                    sessionId: "",
                    sessionNumber: "",
                    userName: "",
                    user: ""

                });
            }


            // ======================================================
            // 6. GET USER SYS ID
            // ======================================================

            var userSysId =
                userGR.getUniqueValue();


            // ======================================================
            // 7. CHECK USER ACTIVE
            // ======================================================

            var active =
                userGR.getValue("active");


            if (active != "1") {

                return JSON.stringify({

                    authentication: false,
                    userRole: "",
                    sessionId: "",
                    sessionNumber: "",
                    userName: "",
                    user: ""

                });
            }


            // ======================================================
            // 8. VARIABLES FOR GROUP / ROLE / PORTAL
            // ======================================================

            var groupName = "";
            var portal = "";
            var roleSysId = "";
            var roleName = "";


            // ======================================================
            // 9. FIND USER GROUPS
            // ======================================================

            var groupGR =
                new GlideRecord("sys_user_grmember");

            groupGR.addQuery(
                "user",
                userSysId
            );

            groupGR.query();


            while (groupGR.next()) {

                var currentGroup =
                    groupGR.group.getDisplayValue();


                // ==================================================
                // HOSTEL STUDENT GROUP
                // ==================================================

                if (
                    currentGroup ==
                    "Hostel Student Group"
                ) {

                    groupName =
                        "Hostel Student Group";

                    portal =
                        "student";

                    roleSysId =
                        "a02c4a64556343107f4429801dee3ec1";

                    roleName =
                        "Student";

                    break;
                }


                // ==================================================
                // MESS STAFF GROUP
                // ==================================================

                if (
                    currentGroup ==
                    "Hostel Mess Staff Group"
                ) {

                    groupName =
                        "Hostel Mess Staff Group";

                    portal =
                        "staff";

                    roleSysId =
                        "efcd524ea92b03107f444d1b3bf57733";

                    roleName =
                        "Staff";

                    break;
                }


                // ==================================================
                // ADMIN GROUP
                // ==================================================

                if (
                    currentGroup ==
                    "Hostel Admin Group"
                ) {

                    groupName =
                        "Hostel Admin Group";

                    portal =
                        "admin";

                    roleSysId =
                        "c632d9d7dd1f03107f44143a6accf806";

                    roleName =
                        "Admin";

                    break;
                }


                // ==================================================
                // MANAGEMENT GROUP
                // ==================================================

                if (
                    currentGroup ==
                    "Hostel Management Group"
                ) {

                    groupName =
                        "Hostel Management Group";

                    portal =
                        "management";

                    roleSysId =
                        "414e528ea92b03107f444d1b3bf57779";

                    roleName =
                        "Manager";

                    break;
                }
            }


            // ======================================================
            // 10. NO VALID GROUP FOUND
            // ======================================================

            if (groupName == "") {

                return JSON.stringify({

                    authentication: false,
                    userRole: "",
                    sessionId: "",
                    sessionNumber: "",
                    userName: "",
                    user: ""

                });
            }


            // ======================================================
            // 11. NO ROLE FOUND
            // ======================================================

            if (roleSysId == "") {

                return JSON.stringify({

                    authentication: false,
                    userRole: "",
                    sessionId: "",
                    sessionNumber: "",
                    userName: "",
                    user: ""

                });
            }


            // ======================================================
            // 12. GENERATE UNIQUE SESSION ID
            // ======================================================

            var sessionId = "";
            var sessionExists = true;


            while (sessionExists) {

                // --------------------------------------------------
                // Generate random 32-character session ID
                // --------------------------------------------------

                sessionId =
                    GlideSecureRandomUtil
                    .getSecureRandomString(32);


                // --------------------------------------------------
                // Check whether session ID already exists
                // --------------------------------------------------

                var sessionCheck =
                    new GlideRecord(
                        "x_snc_campus_foo_1_campus_login_session"
                    );

                sessionCheck.addQuery(
                    "session_id",
                    sessionId
                );

                sessionCheck.query();


                sessionExists =
                    sessionCheck.hasNext();
            }


            // ======================================================
            // 13. CREATE CAMPUS LOGIN SESSION
            // ======================================================

            var sessionGR =
                new GlideRecord(
                    "x_snc_campus_foo_1_campus_login_session"
                );

            sessionGR.initialize();


            // ======================================================
            // USER
            // ======================================================

            sessionGR.setValue(
                "user",
                userSysId
            );


            // ======================================================
            // USER NAME
            // ======================================================

            sessionGR.setValue(
                "user_name",
                userGR.getDisplayValue("name")
            );


            // ======================================================
            // SESSION ID
            // ======================================================

            sessionGR.setValue(
                "session_id",
                sessionId
            );


            // ======================================================
            // ROLE
            // ======================================================

            sessionGR.setValue(
                "role",
                roleSysId
            );


            // ======================================================
            // LOGIN TIME
            // ======================================================

            sessionGR.setValue(
                "login_time",
                new GlideDateTime().getDisplayValue()
            );


            // ======================================================
            // STATUS
            // ======================================================

            sessionGR.setValue(
                "status",
                "active"
            );


            // ======================================================
            // 14. INSERT SESSION RECORD
            // ======================================================

            var newSessionSysId =
                sessionGR.insert();


            // ======================================================
            // 15. SESSION CREATION FAILED
            // ======================================================

            if (!newSessionSysId) {

                return JSON.stringify({

                    authentication: false,
                    userRole: "",
                    sessionId: "",
                    sessionNumber: "",
                    userName: "",
                    user: ""

                });
            }


            // ======================================================
            // 16. GET SESSION NUMBER
            // ======================================================

            var sessionNumber =
                sessionGR.getValue("number");


            // ======================================================
            // 17. GET USER NAME
            // ======================================================

            var userName =
                userGR.getDisplayValue("name");


            // ======================================================
            // 18. RETURN COMPLETE LOGIN RESULT
            // ======================================================

            // These values will be received by the Login Page.
            //
            // The Login Page will store them in localStorage.
            //
            // ======================================================

            var result = {

                authentication: true,
                sessionNumber: sessionNumber,
                sessionId: sessionId,
                userRole: roleName,
                userName: userName,
                user: userSysId

            };


            return JSON.stringify(result);
        },


        // ==========================================================
        // ALLOW PUBLIC / GUEST ACCESS
        // ==========================================================

        isPublic: function() {
            return true;
        },


        // ==========================================================
        // SCRIPT INCLUDE TYPE
        // ==========================================================

        type: "CampusLoginSessionUtils"

    }

);
